PRAGMA foreign_keys=ON;
BEGIN TRANSACTION;
INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-01','HSK9-01','HSK 9 · Đề 01','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 01 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-01-q01','seed-hsk9-01',1,'single_choice','Pinyin phù hợp với “辨证” là phương án nào?','Pinyin của “辨证” là “biànzhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biện chứng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q02','seed-hsk9-01',2,'single_choice','Chọn từ Hán ngữ có nghĩa “tập hợp”.','Từ phù hợp là “聚合”, đọc là jùhé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q03','seed-hsk9-01',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “统摄 — tǒngshè”, nghĩa là “bao quát chi phối”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q04','seed-hsk9-01',4,'single_choice','Từ “洞察” gần nghĩa nhất với phương án nào?','“洞察” (dòngchá) có nghĩa là “thấu hiểu sâu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q05','seed-hsk9-01',5,'single_choice','Pinyin phù hợp với “耦合” là phương án nào?','Pinyin của “耦合” là “ǒuhé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “liên kết tương tác”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q06','seed-hsk9-01',6,'single_choice','Chọn từ Hán ngữ có nghĩa “lặp và cải tiến”.','Từ phù hợp là “迭代”, đọc là diédài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q07','seed-hsk9-01',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “赋能 — fùnéng”, nghĩa là “trao năng lực”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q08','seed-hsk9-01',8,'single_choice','Từ “嵌入” gần nghĩa nhất với phương án nào?','“嵌入” (qiànrù) có nghĩa là “nhúng/gắn vào”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q09','seed-hsk9-01',9,'single_choice','Pinyin phù hợp với “解构” là phương án nào?','Pinyin của “解构” là “jiěgòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q10','seed-hsk9-01',10,'single_choice','Chọn từ Hán ngữ có nghĩa “chuyển dịch”.','Từ phù hợp là “迁移”, đọc là qiānyí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q11','seed-hsk9-01',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “嬗变 — shànbiàn”, nghĩa là “biến đổi dần”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q12','seed-hsk9-01',12,'single_choice','Từ “韧性” gần nghĩa nhất với phương án nào?','“韧性” (rènxìng) có nghĩa là “khả năng thích ứng bền bỉ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q13','seed-hsk9-01',13,'single_choice','Pinyin phù hợp với “映射” là phương án nào?','Pinyin của “映射” là “yìngshè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ánh xạ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q14','seed-hsk9-01',14,'single_choice','Chọn từ Hán ngữ có nghĩa “tái cấu trúc”.','Từ phù hợp là “重构”, đọc là chónggòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q15','seed-hsk9-01',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “溯源 — sùyuán”, nghĩa là “truy nguyên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q16','seed-hsk9-01',16,'single_choice','Từ “范畴” gần nghĩa nhất với phương án nào?','“范畴” (fànchóu) có nghĩa là “phạm trù”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q17','seed-hsk9-01',17,'single_choice','Pinyin phù hợp với “生成” là phương án nào?','Pinyin của “生成” là “shēngchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hình thành”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q18','seed-hsk9-01',18,'single_choice','Chọn từ Hán ngữ có nghĩa “tương tác chiến lược”.','Từ phù hợp là “博弈”, đọc là bóyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q19','seed-hsk9-01',19,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “张力 — zhānglì”, nghĩa là “sức căng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-01-q20','seed-hsk9-01',20,'single_choice','Từ “阈值” gần nghĩa nhất với phương án nào?','“阈值” (yùzhí) có nghĩa là “ngưỡng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
