INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-02','HSK9-02','HSK 9 · Đề 02','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 02 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-02-q01','seed-hsk9-02',1,'single_choice','Pinyin phù hợp với “迁移” là phương án nào?','Pinyin của “迁移” là “qiānyí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuyển dịch”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q02','seed-hsk9-02',2,'single_choice','Chọn từ Hán ngữ có nghĩa “biến đổi dần”.','Từ phù hợp là “嬗变”, đọc là shànbiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q03','seed-hsk9-02',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “韧性 — rènxìng”, nghĩa là “khả năng thích ứng bền bỉ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q04','seed-hsk9-02',4,'single_choice','Từ “映射” gần nghĩa nhất với phương án nào?','“映射” (yìngshè) có nghĩa là “ánh xạ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q05','seed-hsk9-02',5,'single_choice','Pinyin phù hợp với “重构” là phương án nào?','Pinyin của “重构” là “chónggòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tái cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q06','seed-hsk9-02',6,'single_choice','Chọn từ Hán ngữ có nghĩa “truy nguyên”.','Từ phù hợp là “溯源”, đọc là sùyuán. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q07','seed-hsk9-02',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “范畴 — fànchóu”, nghĩa là “phạm trù”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q08','seed-hsk9-02',8,'single_choice','Từ “生成” gần nghĩa nhất với phương án nào?','“生成” (shēngchéng) có nghĩa là “hình thành”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q09','seed-hsk9-02',9,'single_choice','Pinyin phù hợp với “博弈” là phương án nào?','Pinyin của “博弈” là “bóyì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tương tác chiến lược”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q10','seed-hsk9-02',10,'single_choice','Chọn từ Hán ngữ có nghĩa “sức căng”.','Từ phù hợp là “张力”, đọc là zhānglì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q11','seed-hsk9-02',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “阈值 — yùzhí”, nghĩa là “ngưỡng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q12','seed-hsk9-02',12,'single_choice','Từ “辨证” gần nghĩa nhất với phương án nào?','“辨证” (biànzhèng) có nghĩa là “biện chứng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-02-q13','seed-hsk9-02',13,'single_choice','Pinyin phù hợp với “聚合” là phương án nào?','Pinyin của “聚合” là “jùhé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tập hợp”.',NULL,NULL,0,1,'',datetime('now')),
