INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-03','HSK9-03','HSK 9 · Đề 03','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 03 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-03-q01','seed-hsk9-03',1,'single_choice','Pinyin phù hợp với “张力” là phương án nào?','Pinyin của “张力” là “zhānglì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sức căng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q02','seed-hsk9-03',2,'single_choice','Chọn từ Hán ngữ có nghĩa “ngưỡng”.','Từ phù hợp là “阈值”, đọc là yùzhí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q03','seed-hsk9-03',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “辨证 — biànzhèng”, nghĩa là “biện chứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q04','seed-hsk9-03',4,'single_choice','Từ “聚合” gần nghĩa nhất với phương án nào?','“聚合” (jùhé) có nghĩa là “tập hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q05','seed-hsk9-03',5,'single_choice','Pinyin phù hợp với “统摄” là phương án nào?','Pinyin của “统摄” là “tǒngshè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bao quát chi phối”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q06','seed-hsk9-03',6,'single_choice','Chọn từ Hán ngữ có nghĩa “thấu hiểu sâu”.','Từ phù hợp là “洞察”, đọc là dòngchá. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q07','seed-hsk9-03',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “耦合 — ǒuhé”, nghĩa là “liên kết tương tác”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q08','seed-hsk9-03',8,'single_choice','Từ “迭代” gần nghĩa nhất với phương án nào?','“迭代” (diédài) có nghĩa là “lặp và cải tiến”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q09','seed-hsk9-03',9,'single_choice','Pinyin phù hợp với “赋能” là phương án nào?','Pinyin của “赋能” là “fùnéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trao năng lực”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q10','seed-hsk9-03',10,'single_choice','Chọn từ Hán ngữ có nghĩa “nhúng/gắn vào”.','Từ phù hợp là “嵌入”, đọc là qiànrù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q11','seed-hsk9-03',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “解构 — jiěgòu”, nghĩa là “giải cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q12','seed-hsk9-03',12,'single_choice','Từ “迁移” gần nghĩa nhất với phương án nào?','“迁移” (qiānyí) có nghĩa là “chuyển dịch”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-03-q13','seed-hsk9-03',13,'single_choice','Pinyin phù hợp với “嬗变” là phương án nào?','Pinyin của “嬗变” là “shànbiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biến đổi dần”.',NULL,NULL,0,1,'',datetime('now')),
