INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-05','HSK9-05','HSK 9 · Đề 05','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 05 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-05-q01','seed-hsk9-05',1,'single_choice','Pinyin phù hợp với “生成” là phương án nào?','Pinyin của “生成” là “shēngchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hình thành”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q02','seed-hsk9-05',2,'single_choice','Chọn từ Hán ngữ có nghĩa “tương tác chiến lược”.','Từ phù hợp là “博弈”, đọc là bóyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q03','seed-hsk9-05',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “张力 — zhānglì”, nghĩa là “sức căng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q04','seed-hsk9-05',4,'single_choice','Từ “阈值” gần nghĩa nhất với phương án nào?','“阈值” (yùzhí) có nghĩa là “ngưỡng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q05','seed-hsk9-05',5,'single_choice','Pinyin phù hợp với “辨证” là phương án nào?','Pinyin của “辨证” là “biànzhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biện chứng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q06','seed-hsk9-05',6,'single_choice','Chọn từ Hán ngữ có nghĩa “tập hợp”.','Từ phù hợp là “聚合”, đọc là jùhé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q07','seed-hsk9-05',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “统摄 — tǒngshè”, nghĩa là “bao quát chi phối”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q08','seed-hsk9-05',8,'single_choice','Từ “洞察” gần nghĩa nhất với phương án nào?','“洞察” (dòngchá) có nghĩa là “thấu hiểu sâu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q09','seed-hsk9-05',9,'single_choice','Pinyin phù hợp với “耦合” là phương án nào?','Pinyin của “耦合” là “ǒuhé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “liên kết tương tác”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q10','seed-hsk9-05',10,'single_choice','Chọn từ Hán ngữ có nghĩa “lặp và cải tiến”.','Từ phù hợp là “迭代”, đọc là diédài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q11','seed-hsk9-05',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “赋能 — fùnéng”, nghĩa là “trao năng lực”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q12','seed-hsk9-05',12,'single_choice','Từ “嵌入” gần nghĩa nhất với phương án nào?','“嵌入” (qiànrù) có nghĩa là “nhúng/gắn vào”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q13','seed-hsk9-05',13,'single_choice','Pinyin phù hợp với “解构” là phương án nào?','Pinyin của “解构” là “jiěgòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q14','seed-hsk9-05',14,'single_choice','Chọn từ Hán ngữ có nghĩa “chuyển dịch”.','Từ phù hợp là “迁移”, đọc là qiānyí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-05-q15','seed-hsk9-05',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “嬗变 — shànbiàn”, nghĩa là “biến đổi dần”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
