INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-06','HSK9-06','HSK 9 · Đề 06','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 06 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-06-q01','seed-hsk9-06',1,'single_choice','Pinyin phù hợp với “迭代” là phương án nào?','Pinyin của “迭代” là “diédài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lặp và cải tiến”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q02','seed-hsk9-06',2,'single_choice','Chọn từ Hán ngữ có nghĩa “trao năng lực”.','Từ phù hợp là “赋能”, đọc là fùnéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q03','seed-hsk9-06',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “嵌入 — qiànrù”, nghĩa là “nhúng/gắn vào”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q04','seed-hsk9-06',4,'single_choice','Từ “解构” gần nghĩa nhất với phương án nào?','“解构” (jiěgòu) có nghĩa là “giải cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q05','seed-hsk9-06',5,'single_choice','Pinyin phù hợp với “迁移” là phương án nào?','Pinyin của “迁移” là “qiānyí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuyển dịch”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q06','seed-hsk9-06',6,'single_choice','Chọn từ Hán ngữ có nghĩa “biến đổi dần”.','Từ phù hợp là “嬗变”, đọc là shànbiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q07','seed-hsk9-06',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “韧性 — rènxìng”, nghĩa là “khả năng thích ứng bền bỉ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q08','seed-hsk9-06',8,'single_choice','Từ “映射” gần nghĩa nhất với phương án nào?','“映射” (yìngshè) có nghĩa là “ánh xạ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q09','seed-hsk9-06',9,'single_choice','Pinyin phù hợp với “重构” là phương án nào?','Pinyin của “重构” là “chónggòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tái cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q10','seed-hsk9-06',10,'single_choice','Chọn từ Hán ngữ có nghĩa “truy nguyên”.','Từ phù hợp là “溯源”, đọc là sùyuán. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q11','seed-hsk9-06',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “范畴 — fànchóu”, nghĩa là “phạm trù”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q12','seed-hsk9-06',12,'single_choice','Từ “生成” gần nghĩa nhất với phương án nào?','“生成” (shēngchéng) có nghĩa là “hình thành”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q13','seed-hsk9-06',13,'single_choice','Pinyin phù hợp với “博弈” là phương án nào?','Pinyin của “博弈” là “bóyì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tương tác chiến lược”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-06-q14','seed-hsk9-06',14,'single_choice','Chọn từ Hán ngữ có nghĩa “sức căng”.','Từ phù hợp là “张力”, đọc là zhānglì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
