INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-07','HSK9-07','HSK 9 · Đề 07','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 07 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-07-q01','seed-hsk9-07',1,'single_choice','Pinyin phù hợp với “溯源” là phương án nào?','Pinyin của “溯源” là “sùyuán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “truy nguyên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q02','seed-hsk9-07',2,'single_choice','Chọn từ Hán ngữ có nghĩa “phạm trù”.','Từ phù hợp là “范畴”, đọc là fànchóu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q03','seed-hsk9-07',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “生成 — shēngchéng”, nghĩa là “hình thành”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q04','seed-hsk9-07',4,'single_choice','Từ “博弈” gần nghĩa nhất với phương án nào?','“博弈” (bóyì) có nghĩa là “tương tác chiến lược”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q05','seed-hsk9-07',5,'single_choice','Pinyin phù hợp với “张力” là phương án nào?','Pinyin của “张力” là “zhānglì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sức căng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q06','seed-hsk9-07',6,'single_choice','Chọn từ Hán ngữ có nghĩa “ngưỡng”.','Từ phù hợp là “阈值”, đọc là yùzhí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q07','seed-hsk9-07',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “辨证 — biànzhèng”, nghĩa là “biện chứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q08','seed-hsk9-07',8,'single_choice','Từ “聚合” gần nghĩa nhất với phương án nào?','“聚合” (jùhé) có nghĩa là “tập hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q09','seed-hsk9-07',9,'single_choice','Pinyin phù hợp với “统摄” là phương án nào?','Pinyin của “统摄” là “tǒngshè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bao quát chi phối”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q10','seed-hsk9-07',10,'single_choice','Chọn từ Hán ngữ có nghĩa “thấu hiểu sâu”.','Từ phù hợp là “洞察”, đọc là dòngchá. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q11','seed-hsk9-07',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “耦合 — ǒuhé”, nghĩa là “liên kết tương tác”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q12','seed-hsk9-07',12,'single_choice','Từ “迭代” gần nghĩa nhất với phương án nào?','“迭代” (diédài) có nghĩa là “lặp và cải tiến”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q13','seed-hsk9-07',13,'single_choice','Pinyin phù hợp với “赋能” là phương án nào?','Pinyin của “赋能” là “fùnéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trao năng lực”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q14','seed-hsk9-07',14,'single_choice','Chọn từ Hán ngữ có nghĩa “nhúng/gắn vào”.','Từ phù hợp là “嵌入”, đọc là qiànrù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-07-q15','seed-hsk9-07',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “解构 — jiěgòu”, nghĩa là “giải cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
