INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-08','HSK9-08','HSK 9 · Đề 08','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 08 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-08-q01','seed-hsk9-08',1,'single_choice','Pinyin phù hợp với “洞察” là phương án nào?','Pinyin của “洞察” là “dòngchá”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thấu hiểu sâu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q02','seed-hsk9-08',2,'single_choice','Chọn từ Hán ngữ có nghĩa “liên kết tương tác”.','Từ phù hợp là “耦合”, đọc là ǒuhé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q03','seed-hsk9-08',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “迭代 — diédài”, nghĩa là “lặp và cải tiến”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q04','seed-hsk9-08',4,'single_choice','Từ “赋能” gần nghĩa nhất với phương án nào?','“赋能” (fùnéng) có nghĩa là “trao năng lực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q05','seed-hsk9-08',5,'single_choice','Pinyin phù hợp với “嵌入” là phương án nào?','Pinyin của “嵌入” là “qiànrù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhúng/gắn vào”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q06','seed-hsk9-08',6,'single_choice','Chọn từ Hán ngữ có nghĩa “giải cấu trúc”.','Từ phù hợp là “解构”, đọc là jiěgòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q07','seed-hsk9-08',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “迁移 — qiānyí”, nghĩa là “chuyển dịch”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q08','seed-hsk9-08',8,'single_choice','Từ “嬗变” gần nghĩa nhất với phương án nào?','“嬗变” (shànbiàn) có nghĩa là “biến đổi dần”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q09','seed-hsk9-08',9,'single_choice','Pinyin phù hợp với “韧性” là phương án nào?','Pinyin của “韧性” là “rènxìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khả năng thích ứng bền bỉ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q10','seed-hsk9-08',10,'single_choice','Chọn từ Hán ngữ có nghĩa “ánh xạ”.','Từ phù hợp là “映射”, đọc là yìngshè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q11','seed-hsk9-08',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “重构 — chónggòu”, nghĩa là “tái cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q12','seed-hsk9-08',12,'single_choice','Từ “溯源” gần nghĩa nhất với phương án nào?','“溯源” (sùyuán) có nghĩa là “truy nguyên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q13','seed-hsk9-08',13,'single_choice','Pinyin phù hợp với “范畴” là phương án nào?','Pinyin của “范畴” là “fànchóu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phạm trù”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q14','seed-hsk9-08',14,'single_choice','Chọn từ Hán ngữ có nghĩa “hình thành”.','Từ phù hợp là “生成”, đọc là shēngchéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q15','seed-hsk9-08',15,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “博弈 — bóyì”, nghĩa là “tương tác chiến lược”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-08-q16','seed-hsk9-08',16,'single_choice','Từ “张力” gần nghĩa nhất với phương án nào?','“张力” (zhānglì) có nghĩa là “sức căng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
