('seed-hsk9-10-q24','seed-hsk9-10',24,'single_choice','Từ “耦合” gần nghĩa nhất với phương án nào?','“耦合” (ǒuhé) có nghĩa là “liên kết tương tác”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
