('seed-hsk9-11-q19','seed-hsk9-11',19,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “解构 — jiěgòu”, nghĩa là “giải cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-11-q20','seed-hsk9-11',20,'single_choice','Từ “迁移” gần nghĩa nhất với phương án nào?','“迁移” (qiānyí) có nghĩa là “chuyển dịch”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-11-q21','seed-hsk9-11',21,'single_choice','Pinyin phù hợp với “嬗变” là phương án nào?','Pinyin của “嬗变” là “shànbiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biến đổi dần”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-11-q22','seed-hsk9-11',22,'single_choice','Chọn từ Hán ngữ có nghĩa “khả năng thích ứng bền bỉ”.','Từ phù hợp là “韧性”, đọc là rènxìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-11-q23','seed-hsk9-11',23,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “映射 — yìngshè”, nghĩa là “ánh xạ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-11-q24','seed-hsk9-11',24,'single_choice','Từ “重构” gần nghĩa nhất với phương án nào?','“重构” (chónggòu) có nghĩa là “tái cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
