('seed-hsk9-12-q23','seed-hsk9-12',23,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “聚合 — jùhé”, nghĩa là “tập hợp”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-12-q24','seed-hsk9-12',24,'single_choice','Từ “统摄” gần nghĩa nhất với phương án nào?','“统摄” (tǒngshè) có nghĩa là “bao quát chi phối”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-12-q25','seed-hsk9-12',25,'single_choice','Pinyin phù hợp với “洞察” là phương án nào?','Pinyin của “洞察” là “dòngchá”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “thấu hiểu sâu”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-12-q26','seed-hsk9-12',26,'single_choice','Chọn từ Hán ngữ có nghĩa “liên kết tương tác”.','Từ phù hợp là “耦合”, đọc là ǒuhé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-12-q27','seed-hsk9-12',27,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “迭代 — diédài”, nghĩa là “lặp và cải tiến”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-12-q28','seed-hsk9-12',28,'single_choice','Từ “赋能” gần nghĩa nhất với phương án nào?','“赋能” (fùnéng) có nghĩa là “trao năng lực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
