INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-13','HSK9-13','HSK 9 · Đề 13','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 13 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-13-q01','seed-hsk9-13',1,'single_choice','Pinyin phù hợp với “解构” là phương án nào?','Pinyin của “解构” là “jiěgòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q02','seed-hsk9-13',2,'single_choice','Chọn từ Hán ngữ có nghĩa “chuyển dịch”.','Từ phù hợp là “迁移”, đọc là qiānyí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q03','seed-hsk9-13',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “嬗变 — shànbiàn”, nghĩa là “biến đổi dần”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q04','seed-hsk9-13',4,'single_choice','Từ “韧性” gần nghĩa nhất với phương án nào?','“韧性” (rènxìng) có nghĩa là “khả năng thích ứng bền bỉ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q05','seed-hsk9-13',5,'single_choice','Pinyin phù hợp với “映射” là phương án nào?','Pinyin của “映射” là “yìngshè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ánh xạ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q06','seed-hsk9-13',6,'single_choice','Chọn từ Hán ngữ có nghĩa “tái cấu trúc”.','Từ phù hợp là “重构”, đọc là chónggòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q07','seed-hsk9-13',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “溯源 — sùyuán”, nghĩa là “truy nguyên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q08','seed-hsk9-13',8,'single_choice','Từ “范畴” gần nghĩa nhất với phương án nào?','“范畴” (fànchóu) có nghĩa là “phạm trù”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q09','seed-hsk9-13',9,'single_choice','Pinyin phù hợp với “生成” là phương án nào?','Pinyin của “生成” là “shēngchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hình thành”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q10','seed-hsk9-13',10,'single_choice','Chọn từ Hán ngữ có nghĩa “tương tác chiến lược”.','Từ phù hợp là “博弈”, đọc là bóyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
