('seed-hsk9-13-q25','seed-hsk9-13',25,'single_choice','Pinyin phù hợp với “映射” là phương án nào?','Pinyin của “映射” là “yìngshè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ánh xạ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q26','seed-hsk9-13',26,'single_choice','Chọn từ Hán ngữ có nghĩa “tái cấu trúc”.','Từ phù hợp là “重构”, đọc là chónggòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q27','seed-hsk9-13',27,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “溯源 — sùyuán”, nghĩa là “truy nguyên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q28','seed-hsk9-13',28,'single_choice','Từ “范畴” gần nghĩa nhất với phương án nào?','“范畴” (fànchóu) có nghĩa là “phạm trù”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q29','seed-hsk9-13',29,'single_choice','Pinyin phù hợp với “生成” là phương án nào?','Pinyin của “生成” là “shēngchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hình thành”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q30','seed-hsk9-13',30,'single_choice','Chọn từ Hán ngữ có nghĩa “tương tác chiến lược”.','Từ phù hợp là “博弈”, đọc là bóyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q31','seed-hsk9-13',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “张力 — zhānglì”, nghĩa là “sức căng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q32','seed-hsk9-13',32,'single_choice','Từ “阈值” gần nghĩa nhất với phương án nào?','“阈值” (yùzhí) có nghĩa là “ngưỡng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-13-q33','seed-hsk9-13',33,'single_choice','Pinyin phù hợp với “辨证” là phương án nào?','Pinyin của “辨证” là “biànzhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biện chứng”.',NULL,NULL,0,1,'',datetime('now')),
