('seed-hsk9-14-q20','seed-hsk9-14',20,'single_choice','Từ “生成” gần nghĩa nhất với phương án nào?','“生成” (shēngchéng) có nghĩa là “hình thành”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
