('seed-hsk9-14-q27','seed-hsk9-14',27,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “洞察 — dòngchá”, nghĩa là “thấu hiểu sâu”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-14-q28','seed-hsk9-14',28,'single_choice','Từ “耦合” gần nghĩa nhất với phương án nào?','“耦合” (ǒuhé) có nghĩa là “liên kết tương tác”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-14-q29','seed-hsk9-14',29,'single_choice','Pinyin phù hợp với “迭代” là phương án nào?','Pinyin của “迭代” là “diédài”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “lặp và cải tiến”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-14-q30','seed-hsk9-14',30,'single_choice','Chọn từ Hán ngữ có nghĩa “trao năng lực”.','Từ phù hợp là “赋能”, đọc là fùnéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-14-q31','seed-hsk9-14',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “嵌入 — qiànrù”, nghĩa là “nhúng/gắn vào”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-14-q32','seed-hsk9-14',32,'single_choice','Từ “解构” gần nghĩa nhất với phương án nào?','“解构” (jiěgòu) có nghĩa là “giải cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
