INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-15','HSK9-15','HSK 9 · Đề 15','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 15 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-15-q01','seed-hsk9-15',1,'single_choice','Pinyin phù hợp với “赋能” là phương án nào?','Pinyin của “赋能” là “fùnéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trao năng lực”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q02','seed-hsk9-15',2,'single_choice','Chọn từ Hán ngữ có nghĩa “nhúng/gắn vào”.','Từ phù hợp là “嵌入”, đọc là qiànrù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q03','seed-hsk9-15',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “解构 — jiěgòu”, nghĩa là “giải cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q04','seed-hsk9-15',4,'single_choice','Từ “迁移” gần nghĩa nhất với phương án nào?','“迁移” (qiānyí) có nghĩa là “chuyển dịch”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q05','seed-hsk9-15',5,'single_choice','Pinyin phù hợp với “嬗变” là phương án nào?','Pinyin của “嬗变” là “shànbiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biến đổi dần”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q06','seed-hsk9-15',6,'single_choice','Chọn từ Hán ngữ có nghĩa “khả năng thích ứng bền bỉ”.','Từ phù hợp là “韧性”, đọc là rènxìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q07','seed-hsk9-15',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “映射 — yìngshè”, nghĩa là “ánh xạ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q08','seed-hsk9-15',8,'single_choice','Từ “重构” gần nghĩa nhất với phương án nào?','“重构” (chónggòu) có nghĩa là “tái cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q09','seed-hsk9-15',9,'single_choice','Pinyin phù hợp với “溯源” là phương án nào?','Pinyin của “溯源” là “sùyuán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “truy nguyên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q10','seed-hsk9-15',10,'single_choice','Chọn từ Hán ngữ có nghĩa “phạm trù”.','Từ phù hợp là “范畴”, đọc là fànchóu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q11','seed-hsk9-15',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “生成 — shēngchéng”, nghĩa là “hình thành”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q12','seed-hsk9-15',12,'single_choice','Từ “博弈” gần nghĩa nhất với phương án nào?','“博弈” (bóyì) có nghĩa là “tương tác chiến lược”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
