('seed-hsk9-15-q29','seed-hsk9-15',29,'single_choice','Pinyin phù hợp với “溯源” là phương án nào?','Pinyin của “溯源” là “sùyuán”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “truy nguyên”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q30','seed-hsk9-15',30,'single_choice','Chọn từ Hán ngữ có nghĩa “phạm trù”.','Từ phù hợp là “范畴”, đọc là fànchóu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q31','seed-hsk9-15',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “生成 — shēngchéng”, nghĩa là “hình thành”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q32','seed-hsk9-15',32,'single_choice','Từ “博弈” gần nghĩa nhất với phương án nào?','“博弈” (bóyì) có nghĩa là “tương tác chiến lược”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q33','seed-hsk9-15',33,'single_choice','Pinyin phù hợp với “张力” là phương án nào?','Pinyin của “张力” là “zhānglì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sức căng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q34','seed-hsk9-15',34,'single_choice','Chọn từ Hán ngữ có nghĩa “ngưỡng”.','Từ phù hợp là “阈值”, đọc là yùzhí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q35','seed-hsk9-15',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “辨证 — biànzhèng”, nghĩa là “biện chứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q36','seed-hsk9-15',36,'single_choice','Từ “聚合” gần nghĩa nhất với phương án nào?','“聚合” (jùhé) có nghĩa là “tập hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-15-q37','seed-hsk9-15',37,'single_choice','Pinyin phù hợp với “统摄” là phương án nào?','Pinyin của “统摄” là “tǒngshè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bao quát chi phối”.',NULL,NULL,0,1,'',datetime('now')),
