('seed-hsk9-15-q40','seed-hsk9-15',40,'single_choice','Từ “迭代” gần nghĩa nhất với phương án nào?','“迭代” (diédài) có nghĩa là “lặp và cải tiến”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
