('seed-hsk9-16-q31','seed-hsk9-16',31,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “迭代 — diédài”, nghĩa là “lặp và cải tiến”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q32','seed-hsk9-16',32,'single_choice','Từ “赋能” gần nghĩa nhất với phương án nào?','“赋能” (fùnéng) có nghĩa là “trao năng lực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q33','seed-hsk9-16',33,'single_choice','Pinyin phù hợp với “嵌入” là phương án nào?','Pinyin của “嵌入” là “qiànrù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhúng/gắn vào”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q34','seed-hsk9-16',34,'single_choice','Chọn từ Hán ngữ có nghĩa “giải cấu trúc”.','Từ phù hợp là “解构”, đọc là jiěgòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q35','seed-hsk9-16',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “迁移 — qiānyí”, nghĩa là “chuyển dịch”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q36','seed-hsk9-16',36,'single_choice','Từ “嬗变” gần nghĩa nhất với phương án nào?','“嬗变” (shànbiàn) có nghĩa là “biến đổi dần”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q37','seed-hsk9-16',37,'single_choice','Pinyin phù hợp với “韧性” là phương án nào?','Pinyin của “韧性” là “rènxìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khả năng thích ứng bền bỉ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q38','seed-hsk9-16',38,'single_choice','Chọn từ Hán ngữ có nghĩa “ánh xạ”.','Từ phù hợp là “映射”, đọc là yìngshè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q39','seed-hsk9-16',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “重构 — chónggòu”, nghĩa là “tái cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q40','seed-hsk9-16',40,'single_choice','Từ “溯源” gần nghĩa nhất với phương án nào?','“溯源” (sùyuán) có nghĩa là “truy nguyên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q41','seed-hsk9-16',41,'single_choice','Pinyin phù hợp với “范畴” là phương án nào?','Pinyin của “范畴” là “fànchóu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phạm trù”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q42','seed-hsk9-16',42,'single_choice','Chọn từ Hán ngữ có nghĩa “hình thành”.','Từ phù hợp là “生成”, đọc là shēngchéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q43','seed-hsk9-16',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “博弈 — bóyì”, nghĩa là “tương tác chiến lược”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q44','seed-hsk9-16',44,'single_choice','Từ “张力” gần nghĩa nhất với phương án nào?','“张力” (zhānglì) có nghĩa là “sức căng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-16-q45','seed-hsk9-16',45,'single_choice','Pinyin phù hợp với “阈值” là phương án nào?','Pinyin của “阈值” là “yùzhí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngưỡng”.',NULL,NULL,0,1,'',datetime('now')),
