INSERT OR IGNORE INTO exams(id,code,title,group_key,level,duration_minutes,status,require_explanation,description,instructions,total_points,validated_at,published_at,created_at,updated_at) VALUES('seed-hsk9-17','HSK9-17','HSK 9 · Đề 17','hsk','HSK 9',90,'published',1,'Đề luyện HSK 9 số 17 do Nhà Hán Ngữ biên soạn phục vụ luyện tập trên website; không phải đề thi chính thức.','Chọn một đáp án phù hợp nhất cho mỗi câu. Có thể đánh dấu câu để xem lại trước khi nộp.',50,datetime('now'),datetime('now'),datetime('now'),datetime('now'));
INSERT OR IGNORE INTO questions(id,exam_id,position,type,content,explanation,audio_key,image_key,requires_audio,points,tts_text,created_at) VALUES
('seed-hsk9-17-q01','seed-hsk9-17',1,'single_choice','Pinyin phù hợp với “耦合” là phương án nào?','Pinyin của “耦合” là “ǒuhé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “liên kết tương tác”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q02','seed-hsk9-17',2,'single_choice','Chọn từ Hán ngữ có nghĩa “lặp và cải tiến”.','Từ phù hợp là “迭代”, đọc là diédài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q03','seed-hsk9-17',3,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “赋能 — fùnéng”, nghĩa là “trao năng lực”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q04','seed-hsk9-17',4,'single_choice','Từ “嵌入” gần nghĩa nhất với phương án nào?','“嵌入” (qiànrù) có nghĩa là “nhúng/gắn vào”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q05','seed-hsk9-17',5,'single_choice','Pinyin phù hợp với “解构” là phương án nào?','Pinyin của “解构” là “jiěgòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q06','seed-hsk9-17',6,'single_choice','Chọn từ Hán ngữ có nghĩa “chuyển dịch”.','Từ phù hợp là “迁移”, đọc là qiānyí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q07','seed-hsk9-17',7,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “嬗变 — shànbiàn”, nghĩa là “biến đổi dần”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q08','seed-hsk9-17',8,'single_choice','Từ “韧性” gần nghĩa nhất với phương án nào?','“韧性” (rènxìng) có nghĩa là “khả năng thích ứng bền bỉ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q09','seed-hsk9-17',9,'single_choice','Pinyin phù hợp với “映射” là phương án nào?','Pinyin của “映射” là “yìngshè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ánh xạ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q10','seed-hsk9-17',10,'single_choice','Chọn từ Hán ngữ có nghĩa “tái cấu trúc”.','Từ phù hợp là “重构”, đọc là chónggòu. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q11','seed-hsk9-17',11,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “溯源 — sùyuán”, nghĩa là “truy nguyên”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q12','seed-hsk9-17',12,'single_choice','Từ “范畴” gần nghĩa nhất với phương án nào?','“范畴” (fànchóu) có nghĩa là “phạm trù”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
