('seed-hsk9-17-q33','seed-hsk9-17',33,'single_choice','Pinyin phù hợp với “生成” là phương án nào?','Pinyin của “生成” là “shēngchéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “hình thành”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q34','seed-hsk9-17',34,'single_choice','Chọn từ Hán ngữ có nghĩa “tương tác chiến lược”.','Từ phù hợp là “博弈”, đọc là bóyì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q35','seed-hsk9-17',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “张力 — zhānglì”, nghĩa là “sức căng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q36','seed-hsk9-17',36,'single_choice','Từ “阈值” gần nghĩa nhất với phương án nào?','“阈值” (yùzhí) có nghĩa là “ngưỡng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q37','seed-hsk9-17',37,'single_choice','Pinyin phù hợp với “辨证” là phương án nào?','Pinyin của “辨证” là “biànzhèng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biện chứng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q38','seed-hsk9-17',38,'single_choice','Chọn từ Hán ngữ có nghĩa “tập hợp”.','Từ phù hợp là “聚合”, đọc là jùhé. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q39','seed-hsk9-17',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “统摄 — tǒngshè”, nghĩa là “bao quát chi phối”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q40','seed-hsk9-17',40,'single_choice','Từ “洞察” gần nghĩa nhất với phương án nào?','“洞察” (dòngchá) có nghĩa là “thấu hiểu sâu”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q41','seed-hsk9-17',41,'single_choice','Pinyin phù hợp với “耦合” là phương án nào?','Pinyin của “耦合” là “ǒuhé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “liên kết tương tác”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q42','seed-hsk9-17',42,'single_choice','Chọn từ Hán ngữ có nghĩa “lặp và cải tiến”.','Từ phù hợp là “迭代”, đọc là diédài. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
