('seed-hsk9-17-q44','seed-hsk9-17',44,'single_choice','Từ “嵌入” gần nghĩa nhất với phương án nào?','“嵌入” (qiànrù) có nghĩa là “nhúng/gắn vào”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q45','seed-hsk9-17',45,'single_choice','Pinyin phù hợp với “解构” là phương án nào?','Pinyin của “解构” là “jiěgòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “giải cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-17-q46','seed-hsk9-17',46,'single_choice','Chọn từ Hán ngữ có nghĩa “chuyển dịch”.','Từ phù hợp là “迁移”, đọc là qiānyí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
