('seed-hsk9-17-q48','seed-hsk9-17',48,'single_choice','Từ “韧性” gần nghĩa nhất với phương án nào?','“韧性” (rènxìng) có nghĩa là “khả năng thích ứng bền bỉ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
