('seed-hsk9-18-q35','seed-hsk9-18',35,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “嵌入 — qiànrù”, nghĩa là “nhúng/gắn vào”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q36','seed-hsk9-18',36,'single_choice','Từ “解构” gần nghĩa nhất với phương án nào?','“解构” (jiěgòu) có nghĩa là “giải cấu trúc”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q37','seed-hsk9-18',37,'single_choice','Pinyin phù hợp với “迁移” là phương án nào?','Pinyin của “迁移” là “qiānyí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “chuyển dịch”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q38','seed-hsk9-18',38,'single_choice','Chọn từ Hán ngữ có nghĩa “biến đổi dần”.','Từ phù hợp là “嬗变”, đọc là shànbiàn. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q39','seed-hsk9-18',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “韧性 — rènxìng”, nghĩa là “khả năng thích ứng bền bỉ”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q40','seed-hsk9-18',40,'single_choice','Từ “映射” gần nghĩa nhất với phương án nào?','“映射” (yìngshè) có nghĩa là “ánh xạ”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q41','seed-hsk9-18',41,'single_choice','Pinyin phù hợp với “重构” là phương án nào?','Pinyin của “重构” là “chónggòu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tái cấu trúc”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q42','seed-hsk9-18',42,'single_choice','Chọn từ Hán ngữ có nghĩa “truy nguyên”.','Từ phù hợp là “溯源”, đọc là sùyuán. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q43','seed-hsk9-18',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “范畴 — fànchóu”, nghĩa là “phạm trù”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q44','seed-hsk9-18',44,'single_choice','Từ “生成” gần nghĩa nhất với phương án nào?','“生成” (shēngchéng) có nghĩa là “hình thành”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q45','seed-hsk9-18',45,'single_choice','Pinyin phù hợp với “博弈” là phương án nào?','Pinyin của “博弈” là “bóyì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tương tác chiến lược”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q46','seed-hsk9-18',46,'single_choice','Chọn từ Hán ngữ có nghĩa “sức căng”.','Từ phù hợp là “张力”, đọc là zhānglì. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q47','seed-hsk9-18',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “阈值 — yùzhí”, nghĩa là “ngưỡng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q48','seed-hsk9-18',48,'single_choice','Từ “辨证” gần nghĩa nhất với phương án nào?','“辨证” (biànzhèng) có nghĩa là “biện chứng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q49','seed-hsk9-18',49,'single_choice','Pinyin phù hợp với “聚合” là phương án nào?','Pinyin của “聚合” là “jùhé”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “tập hợp”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-18-q50','seed-hsk9-18',50,'single_choice','Chọn từ Hán ngữ có nghĩa “bao quát chi phối”.','Từ phù hợp là “统摄”, đọc là tǒngshè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
