('seed-hsk9-19-q37','seed-hsk9-19',37,'single_choice','Pinyin phù hợp với “张力” là phương án nào?','Pinyin của “张力” là “zhānglì”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “sức căng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q38','seed-hsk9-19',38,'single_choice','Chọn từ Hán ngữ có nghĩa “ngưỡng”.','Từ phù hợp là “阈值”, đọc là yùzhí. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q39','seed-hsk9-19',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “辨证 — biànzhèng”, nghĩa là “biện chứng”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q40','seed-hsk9-19',40,'single_choice','Từ “聚合” gần nghĩa nhất với phương án nào?','“聚合” (jùhé) có nghĩa là “tập hợp”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q41','seed-hsk9-19',41,'single_choice','Pinyin phù hợp với “统摄” là phương án nào?','Pinyin của “统摄” là “tǒngshè”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “bao quát chi phối”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q42','seed-hsk9-19',42,'single_choice','Chọn từ Hán ngữ có nghĩa “thấu hiểu sâu”.','Từ phù hợp là “洞察”, đọc là dòngchá. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q43','seed-hsk9-19',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “耦合 — ǒuhé”, nghĩa là “liên kết tương tác”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q44','seed-hsk9-19',44,'single_choice','Từ “迭代” gần nghĩa nhất với phương án nào?','“迭代” (diédài) có nghĩa là “lặp và cải tiến”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q45','seed-hsk9-19',45,'single_choice','Pinyin phù hợp với “赋能” là phương án nào?','Pinyin của “赋能” là “fùnéng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “trao năng lực”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q46','seed-hsk9-19',46,'single_choice','Chọn từ Hán ngữ có nghĩa “nhúng/gắn vào”.','Từ phù hợp là “嵌入”, đọc là qiànrù. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q47','seed-hsk9-19',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “解构 — jiěgòu”, nghĩa là “giải cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q48','seed-hsk9-19',48,'single_choice','Từ “迁移” gần nghĩa nhất với phương án nào?','“迁移” (qiānyí) có nghĩa là “chuyển dịch”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q49','seed-hsk9-19',49,'single_choice','Pinyin phù hợp với “嬗变” là phương án nào?','Pinyin của “嬗变” là “shànbiàn”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “biến đổi dần”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-19-q50','seed-hsk9-19',50,'single_choice','Chọn từ Hán ngữ có nghĩa “khả năng thích ứng bền bỉ”.','Từ phù hợp là “韧性”, đọc là rènxìng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
