('seed-hsk9-20-q16','seed-hsk9-20',16,'single_choice','Từ “赋能” gần nghĩa nhất với phương án nào?','“赋能” (fùnéng) có nghĩa là “trao năng lực”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q17','seed-hsk9-20',17,'single_choice','Pinyin phù hợp với “嵌入” là phương án nào?','Pinyin của “嵌入” là “qiànrù”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “nhúng/gắn vào”.',NULL,NULL,0,1,'',datetime('now')),
