('seed-hsk9-20-q39','seed-hsk9-20',39,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “迁移 — qiānyí”, nghĩa là “chuyển dịch”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q40','seed-hsk9-20',40,'single_choice','Từ “嬗变” gần nghĩa nhất với phương án nào?','“嬗变” (shànbiàn) có nghĩa là “biến đổi dần”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q41','seed-hsk9-20',41,'single_choice','Pinyin phù hợp với “韧性” là phương án nào?','Pinyin của “韧性” là “rènxìng”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “khả năng thích ứng bền bỉ”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q42','seed-hsk9-20',42,'single_choice','Chọn từ Hán ngữ có nghĩa “ánh xạ”.','Từ phù hợp là “映射”, đọc là yìngshè. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q43','seed-hsk9-20',43,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “重构 — chónggòu”, nghĩa là “tái cấu trúc”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q44','seed-hsk9-20',44,'single_choice','Từ “溯源” gần nghĩa nhất với phương án nào?','“溯源” (sùyuán) có nghĩa là “truy nguyên”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q45','seed-hsk9-20',45,'single_choice','Pinyin phù hợp với “范畴” là phương án nào?','Pinyin của “范畴” là “fànchóu”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “phạm trù”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q46','seed-hsk9-20',46,'single_choice','Chọn từ Hán ngữ có nghĩa “hình thành”.','Từ phù hợp là “生成”, đọc là shēngchéng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q47','seed-hsk9-20',47,'single_choice','Chọn cặp chữ Hán – pinyin đúng.','Cặp đúng là “博弈 — bóyì”, nghĩa là “tương tác chiến lược”. Nên ghi nhớ đồng thời mặt chữ, âm đọc và nghĩa.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q48','seed-hsk9-20',48,'single_choice','Từ “张力” gần nghĩa nhất với phương án nào?','“张力” (zhānglì) có nghĩa là “sức căng”. Câu hỏi kiểm tra khả năng nhận diện nghĩa từ vựng ở HSK 9.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q49','seed-hsk9-20',49,'single_choice','Pinyin phù hợp với “阈值” là phương án nào?','Pinyin của “阈值” là “yùzhí”. Khi ôn, nên đọc thành tiếng và liên hệ với nghĩa “ngưỡng”.',NULL,NULL,0,1,'',datetime('now')),
('seed-hsk9-20-q50','seed-hsk9-20',50,'single_choice','Chọn từ Hán ngữ có nghĩa “biện chứng”.','Từ phù hợp là “辨证”, đọc là biànzhèng. Đây là dạng nhận diện ngược từ nghĩa tiếng Việt sang chữ Hán.',NULL,NULL,0,1,'',datetime('now'));
